/**
 * Trello Node - Version 1
 * Discriminator: resource=attachment, operation=getAll
 */


interface Credentials {
  trelloApi: CredentialReference;
  trelloOAuth1Api: CredentialReference;
}

/** Returns many attachments for the card */
export type TrelloV1AttachmentGetAllParams = {
  resource: 'attachment';
  operation: 'getAll';
  authentication?: 'apiKey' | 'oAuth1' | Expression<string>;
/**
 * The ID of the card
 * @searchListMethod searchCards
 * @default {"mode":"list","value":""}
 */
    cardId?: { __rl: true; mode: 'list' | 'url' | 'id'; value: string; cachedResultName?: string };
/**
 * Additional Fields
 * @default {}
 */
    additionalFields?: {
    /** Fields to return. Either "all" or a comma-separated list of fields.
     * @default all
     */
    fields?: string | Expression<string>;
  };
};

export type TrelloV1AttachmentGetAllOutput = {
  date?: string;
  fileName?: string;
  id?: string;
  idMember?: string;
  isUpload?: boolean;
  mimeType?: string;
  name?: string;
  pos?: number;
  previews?: Array<{
    _id?: string;
    bytes?: number;
    height?: number;
    id?: string;
    scaled?: boolean;
    url?: string;
    width?: number;
  }>;
  url?: string;
};

export type TrelloV1AttachmentGetAllNode = {
  type: 'n8n-nodes-base.trello';
  version: 1;
  config: NodeConfig<TrelloV1AttachmentGetAllParams> & { credentials?: Credentials };
  output?: Items<TrelloV1AttachmentGetAllOutput>;
};